import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BG8d4IEm.js";const u=JSON.parse('{"title":"理解版本命名及限定规则","description":"","frontmatter":{"tags":["计算机基础","规范"]},"headers":[],"relativePath":"posts/2017-09-26-version.md","filePath":"posts/2017-09-26-version.md"}'),l={name:"posts/2017-09-26-version.md"};function d(r,e,o,p,c,i){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="理解版本命名及限定规则" tabindex="-1">理解版本命名及限定规则 <a class="header-anchor" href="#理解版本命名及限定规则" aria-label="Permalink to &quot;理解版本命名及限定规则&quot;">​</a></h1><p><strong>版本命名和版本限定的相关知识</strong></p><h2 id="版本命名规则" tabindex="-1">版本命名规则 <a class="header-anchor" href="#版本命名规则" aria-label="Permalink to &quot;版本命名规则&quot;">​</a></h2><p>我们常见的版本命名格式为</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>[name].x.y.z-[state]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><p><code>name</code>为可选字段,一般为 <code>v</code>,表示 version</p></li><li><p><code>x.y.z</code> 为各版本的序号，遵循 <a href="http://semver.org/lang/zh-CN/" target="_blank" rel="noreferrer">语义化版本命名规范</a><strong>实际上基于此规范,不应该在版本前出现 name 字段.</strong></p></li><li><p><code>state</code> 可选字段,表示版本状态,例如 <code>b</code> 表示 beta 测试版,其他常见状态,后有详述</p></li></ul><h3 id="语义化版本命名规则" tabindex="-1">语义化版本命名规则 <a class="header-anchor" href="#语义化版本命名规则" aria-label="Permalink to &quot;语义化版本命名规则&quot;">​</a></h3><p>该规则对版本的迭代命名,做了很好的限制. 核心规则如下.</p><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">格式要求</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">x</td><td style="text-align:left;">非负整数</td><td style="text-align:left;">主版本号(major)，进行不向下兼容的修改时，递增主版本号</td></tr><tr><td style="text-align:left;">y</td><td style="text-align:left;">非负整数</td><td style="text-align:left;">次版本号(minor)，保持向下兼容,新增特性时，递增次版本号</td></tr><tr><td style="text-align:left;">z</td><td style="text-align:left;">非负整数</td><td style="text-align:left;">修订号(patch),保持向下兼容,修复问题但不影响特性时，递增修订号</td></tr></tbody></table><ul><li><code>0.y.z</code> 表示开发阶段，一切可能随时改变，非稳定版。</li><li><code>1.0.0</code> 界定此版本为初始稳定版，后面的一切更新都基于此版本进行修改。</li></ul><h3 id="版本状态" tabindex="-1">版本状态 <a class="header-anchor" href="#版本状态" aria-label="Permalink to &quot;版本状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">描述方式</th><th>说明</th><th>含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>α</code>或<code>a</code></td><td>alpha 版</td><td>内测版本，内部测试的版本，bug 较多</td></tr><tr><td style="text-align:left;"><code>β</code>或<code>b</code></td><td>beta 版</td><td>公测版本，给外部进行测试的版本，有缺陷</td></tr><tr><td style="text-align:left;"><code>γ</code>或<code>g</code></td><td>Gamma 版</td><td>相当成熟的测试版，于发行版相差无几</td></tr><tr><td style="text-align:left;"><code>rc</code></td><td>Release Candidate</td><td>是前面三种测试版的进一步版本，实现了全部功能，清除了大部分 bug，接近发布倒计时，有时会进一步细分为 rc1,rc2</td></tr></tbody></table><blockquote><p>实际上大部分前端工具均遵守上述规则</p></blockquote><p>在商业软件中还会见到如下字段.</p><table tabindex="0"><thead><tr><th style="text-align:left;">描述方式</th><th>说明</th><th>含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Demo</code></td><td>演示版</td><td>只集成了正式版部分功能，无法升级</td></tr><tr><td style="text-align:left;"><code>SP</code></td><td>SP1</td><td>是 service pack 的意思表示升级包</td></tr><tr><td style="text-align:left;"><code>Trial</code></td><td>试用版</td><td>试用版</td></tr><tr><td style="text-align:left;"><code>Unregistered</code></td><td>未注册</td><td>有功能或时间限制的版本</td></tr><tr><td style="text-align:left;"><code>Lite</code></td><td>精简版</td><td>只含有正式版核心功能</td></tr><tr><td style="text-align:left;"><code>enhance</code></td><td>增强版</td><td>属于正式版1</td></tr><tr><td style="text-align:left;"><code>free</code></td><td>免费版</td><td>自由使用版本</td></tr><tr><td style="text-align:left;"><code>release</code></td><td>发行版</td><td>有时间限制</td></tr><tr><td style="text-align:left;"><code>upgrade</code></td><td>升级版</td><td>有功能增强或修复 bug</td></tr><tr><td style="text-align:left;"><code>Retail</code></td><td>零售版</td><td>单独发售</td></tr><tr><td style="text-align:left;"><code>Cardware</code></td><td>共享版</td><td>公用许可证</td></tr></tbody></table><h2 id="版本限定" tabindex="-1">版本限定 <a class="header-anchor" href="#版本限定" aria-label="Permalink to &quot;版本限定&quot;">​</a></h2><p>在进行包管理时,为了保证安装依赖的兼容性. 必须对依赖包版本进行限定.参考 <a href="https://docs.npmjs.com/misc/semver" target="_blank" rel="noreferrer">npm 限定描述</a> 举例如下</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;devDependencies&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;karma&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;0.13.22&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>表示安装 <code>0.13.22</code> 版本的 karma.</p><p>为了方便理解,版本限定的语法简述为为 <code>[范围描述]&lt;版本号描述&gt;</code></p><ul><li><p>范围描述可选,必须配和版本描述确定范围,无法独立存在</p><ul><li><p><code>&lt;</code> 小于某一版本号</p></li><li><p><code>&lt;=</code> 小于等于某一版本号</p></li><li><p><code>&gt;</code> 大于某一版本号</p></li><li><p><code>&gt;=</code> 大于等于某一版本号</p></li><li><p><code>=</code> 等于某一版本号,没有意义和直接写该版本号一样</p></li><li><p><code>~</code> 基于版本号描述的最新补丁版本</p></li><li><p><code>^</code> 基于版本号描述的最新兼容版本</p></li><li><p><code>-</code> 某个范围,<strong>他应该出现在两个版本描述中间,实际上语法应为 <code>&lt;版本描述&gt;-&lt;版本描述&gt;</code>,写在此处为了统一</strong></p><p>严格来讲对 <code>~,^</code> 的表述需要结合具体的包管理工具和版本号规则来确定.但是对于一般使用记住如下原则. <strong><code>^</code> 是确保版本兼容性时,默认对次版本号的限定约束</strong><strong><code>~</code> 是确保版本兼容性时,默认对补丁号的约束</strong></p></li></ul><blockquote><p>利用 <code>^,~</code> 的意义在于确保工具包对依赖版本的兼容性,排除主版本更迭, 造成依赖失效的可能.</p></blockquote></li><li><p>版本描述</p><ul><li><code>*</code> 通配符,类似 <code>glob</code> 模式 <code>*</code></li><li><code>x,X</code> 约等于 <code>*</code> 号,通常用于次版本和补丁的通配.</li><li><code>0</code> 警惕这个字符,说明该依赖还未稳定(<strong>如果它遵守语义化命名的话</strong>),此外当该字符出现在最前面时,会改变 <code>^,~</code> 的限定特性.</li></ul></li></ul><p>相关举例如下</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt; 1.2.3     小于1.2.3 的版本均可 </span></span>
<span class="line"><span>= 1.2.3     只支持等于1.2.3 的版本 </span></span>
<span class="line"><span>&lt;= 1.2.3    只支持小于等于1.2.3 的版本</span></span>
<span class="line"><span>&gt; 1.2.3     只支持大于 1.2.3 的版本</span></span>
<span class="line"><span>&gt;= 1.2.3    只支持大于等于 1.2.3 的版本</span></span>
<span class="line"><span>1.2.3-2     支持 &gt;=1.2.3 &lt;3.0.0 的版本</span></span>
<span class="line"><span>1.x.1       支持 &gt;=1.0.1 &lt;1.1.0 的版本</span></span>
<span class="line"><span>*           支持 &gt;= 0.0.0 的版本</span></span>
<span class="line"><span>&quot;&quot;          同 *</span></span>
<span class="line"><span>1           表示 &gt;=1.0.0 &lt;2.0.0 其余任意位置为空相似</span></span>
<span class="line"><span>1.0         &gt;= 1.0.0 &lt; 1.1.0</span></span>
<span class="line"><span>~1.1.1      &gt;=1.1.1 &lt;1.2.0</span></span>
<span class="line"><span>~1.1        &gt;=1.1.0 &lt;1.2.0</span></span>
<span class="line"><span>~1          &gt;=1.0.0 &lt;2.0.0</span></span>
<span class="line"><span>^1.1.1      &gt;=1.1.1 &lt;2.0.0</span></span>
<span class="line"><span>^0.1.1      &gt;=0.1.1 &lt;0.2.0 注意这里,不要以为是 0.1.1-1.0.0 之间</span></span>
<span class="line"><span>^0.0.1      &gt;=0.0.1 &lt;0.0.2 同上,请注意</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><blockquote><p>注意大部分包管理工具均遵守上述规则,但是在进行版本限定时,请参考包管理工具的配置项说明,确定语法格式.</p></blockquote><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>最常用的知识</p><h3 id="核心命名规则" tabindex="-1">核心命名规则 <a class="header-anchor" href="#核心命名规则" aria-label="Permalink to &quot;核心命名规则&quot;">​</a></h3><ul><li>版本号通常称为 <code>x.y.z</code><ul><li>x 主版本号,一般向下不兼容时增加此值</li><li>y 次版本号,向下兼容,添加新特性时增加此值</li><li>z 补丁号,修复问题为改变特性时增加此值</li><li><code>a,b,rc</code> 分别表示 内测,公测,发行状态</li></ul></li></ul><h3 id="版本限定-1" tabindex="-1">版本限定 <a class="header-anchor" href="#版本限定-1" aria-label="Permalink to &quot;版本限定&quot;">​</a></h3><ul><li><code>~</code> 在依赖版本兼容下,最近的补丁版</li><li><code>^</code> 在依赖版本兼容下,最近的次版本</li></ul><blockquote><p>重点是保证版本依赖的兼容性,不允许出现依赖的主版本号范围可变,即使你的开发包依旧可用</p></blockquote><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="http://semver.org/lang/zh-CN/" target="_blank" rel="noreferrer">语义化版本规范</a></p><p><a href="https://docs.npmjs.com/misc/semver" target="_blank" rel="noreferrer">npm 版本说明</a></p><p><a href="https://getcomposer.org/doc/articles/versions.md" target="_blank" rel="noreferrer">composer version constraints</a></p><p><a href="http://wenku.baidu.com/view/267166728e9951e79b892703.html" target="_blank" rel="noreferrer">百度文库-版本说明详解</a></p><p><a href="https://www.wikiwand.com/en/Software_versioning" target="_blank" rel="noreferrer">wiki 软件版本</a></p><p><a href="http://serve.3ezy.com/stackoverflow.com/questions/22343224/" target="_blank" rel="noreferrer">What&#39;s the difference between tilde(~) and caret(^) in package.json</a></p>`,38)])])}const h=t(l,[["render",d]]);export{u as __pageData,h as default};
